# ===== hourly v3 observability (v3.0) =====
def _v3_obs_load_k():
    p = os.path.join(config.KALSHI_DIR, "hourly_v3_k.json")
    try:
        with open(p) as f:
            return json.load(f)
    except Exception:
        return {}

def _v3_obs_grades(limit=None):
    p = os.path.join(config.KALSHI_DIR, "hourly_v3_grades.jsonl")
    rows = []
    try:
        with open(p) as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    rows.append(json.loads(line))
                except Exception:
                    pass
    except Exception:
        pass
    return rows[-limit:] if limit else rows

def _v3_obs_bank_n():
    p = os.path.join(config.KALSHI_DIR, "sell_warmup_v3_residuals.csv")
    try:
        with open(p) as f:
            n = sum(1 for _ in f) - 1
        return max(n, 0)
    except Exception:
        return 0

def _mae(vals):
    vals = [v for v in vals if v is not None]
    return round(sum(abs(v) for v in vals) / len(vals), 4) if vals else None

@app.route("/api/hourly_v3")
def api_hourly_v3():
    k = _v3_obs_load_k()
    grades = _v3_obs_grades()
    bank_n = _v3_obs_bank_n()
    eb = [r.get("err_blend") for r in grades]
    ev = [r.get("err_v3") for r in grades]
    by_day = {}
    for r in grades:
        d = str(r.get("hour_et", ""))[:10]
        by_day.setdefault(d, {"err_blend": [], "err_v3": []})
        if r.get("err_blend") is not None:
            by_day[d]["err_blend"].append(r["err_blend"])
        if r.get("err_v3") is not None:
            by_day[d]["err_v3"].append(r["err_v3"])
    daily = [{"date": d,
              "n": len(v["err_v3"]) or len(v["err_blend"]),
              "mae_blend": _mae(v["err_blend"]),
              "mae_v3": _mae(v["err_v3"])}
             for d, v in sorted(by_day.items())][-14:]
    return jsonify({
        "k_dir": k.get("k_dir"),
        "n_fit": k.get("n_fit"),
        "k_updated_at": k.get("updated_at"),
        "bank_n": bank_n,
        "n_graded": len(grades),
        "mae_blend": _mae(eb),
        "mae_v3": _mae(ev),
        "daily": daily,
        "latest": grades[-5:],
    })

